import { z } from 'zod';
import { httpUrlSchema, type DestinationDefinition } from './definition.js';

/**
 * Generic webhook: an HMAC-SHA256-signed JSON POST to the configured URL. The signing
 * secret is generated by the Instance (D10); the URL is not a secret, the signature
 * authenticates the call.
 */
export const webhookDefinition = {
  config: z.strictObject({ url: httpUrlSchema }),
  secrets: z.strictObject({}),
  generatedSecrets: ['signingSecret'],
} as const satisfies DestinationDefinition;

export type WebhookConfig = z.output<typeof webhookDefinition.config>;
export type WebhookSecrets = Readonly<
  Record<(typeof webhookDefinition.generatedSecrets)[number], string>
>;
